  TF_EXPECT_OK(CheckSplitProviderFullIteration(
      params, CreateTensors<int64_t>(TensorShape({}),
                                     {{6}, {2}, {3}, {8}, {7}, {0}, {10}})));
  TF_EXPECT_OK(CheckSplitProviderShardedIteration(
      params, 3, 1,
      CreateTensors<int64_t>(TensorShape({}), {{2}, {7}})));
}
}  
}  
