template <typename T, typename Predicate>
inline ABSL_ATTRIBUTE_ALWAYS_INLINE std::optional<size_t> SmallLinearSearch(
    absl::Span<const T> array, Predicate predicate) {
  if (array.size() <= 2) {
    if (array.empty() || predicate(array[0])) {
