namespace xla {
namespace ifrt {
class DType {
 public:
  enum Kind {
    kInvalid = 0,
    kPred = 1,
    kS2 = 26,
    kS4 = 21,
    kS8 = 2,
    kS16 = 3,
    kS32 = 4,
    kS64 = 5,
    kU2 = 27,
