    kF16 = 10,
    kF32 = 11,
    kF64 = 12,
    kBF16 = 16,
    kC64 = 15,   
    kC128 = 18,  
    kToken = 17,
    kF8E4M3FN = 20,
    kF8E4M3B11FNUZ = 23,
    kF8E4M3FNUZ = 25,
    kF8E5M2 = 19,
    kF8E5M2FNUZ = 24,
    kString = 99,
  };
  explicit DType(Kind kind) : kind_(kind) {}
  DType(const DType&) = default;
  DType(DType&&) = default;
