  }
  ASSERT_EQ(switch_count, 2);
  ASSERT_EQ(merge_count, 1);
  ASSERT_EQ(node_called_case_count, 1);
  ClientSession session(root, SessionOptionsWithInlining());
  {
    ClientSession::FeedType feeds;
