class EvalVisitorParameterizedTest
    : public ::testing::TestWithParam<TestParams> {
 protected:
  EvalVisitorParameterizedTest() {
    CHECK_OK(InitArolla());
    if (GetParam().use_default_optimizer) {
      auto optimizer_or = DefaultOptimizer();
