class ConvolutionThunk : public Thunk {
 public:
  ConvolutionThunk(ThunkInfo thunk_info, GpuConvConfig config,
                   std::vector<BufferAllocation::Slice> operand_slices,
                   std::vector<BufferAllocation::Slice> result_slices,
