MATCHER_P2(DefinesHomogenousOverload, name, argument_type,
           absl::StrCat(name, " for ", CelValue::TypeName(argument_type))) {
  const CelFunctionRegistry& registry = arg;
  return !registry
              .FindOverloads(name, false,
                             {argument_type, argument_type})
              .empty();
  return false;
}
