class EnableIrPrintingTest : public ::testing::Test {
 protected:
  EnableIrPrintingTest() : env_(tsl::Env::Default()) {
    if (!tsl::io::GetTestUndeclaredOutputsDir(&test_dir_)) {
      test_dir_ = tsl::testing::TmpDir();
