      *mlir_module_, DeviceType(DEVICE_TPU_XLA_JIT)));
  FuncOp main = mlir_module_->lookupSymbol<FuncOp>("main");
  ASSERT_TRUE(main);
  bool has_cluster_op = false;
  main.walk([&](mlir::tf_device::ClusterOp) {
