class DefaultCredentialProviderTest : public ::testing::Test {
 protected:
  void SetUp() override {
    UnsetEnv("AWS_ACCESS_KEY_ID");
    UnsetEnv("AWS_SECRET_ACCESS_KEY");
    UnsetEnv("AWS_SESSION_TOKEN");
  }
