      tsl::WriteStringToFile(tsl::Env::Default(), fname, contents).ok());
  Literal literal = TextLiteralReader::ReadPath(fname).value();
  EXPECT_TRUE(
      ShapeUtil::Equal(ShapeUtil::MakeShape(F32, {1, 2, 3}), literal.shape()));
