  EXPECT_EQ(44.5, literal.Get<float>({0, 0, 2}));
  EXPECT_EQ(45.5, literal.Get<float>({0, 1, 0}));
  EXPECT_EQ(46.5, literal.Get<float>({0, 1, 1}));
  EXPECT_EQ(47.5, literal.Get<float>({0, 1, 2}));
}
