              ::testing::StartsWith(
                  "whose sub value doesn't match, where the difference is:"));
}
TEST(JsonSubValuesMatchTest, Example) {
  ::nlohmann::json obj{{"a", 123}, {"b", {{"c", "xyz"}}}};
  EXPECT_THAT(obj, JsonSubValuesMatch({{"/a", 123}, {"/b/c", "xyz"}}));
