    kernel_ctor.construct_arguments(2).Assign(regs.Use({"f0", "f1"}));
    kernel_ctor.construct_last_uses(2).Assign({true, true});
    kernel_ctor.construct_results(2).Assign(
        regs.Def(absl::Span<const std::string>{"r0", "r1"}));
  }
