  int n = 0;
  tensorflow::mutex m;
  for (int i = 0; i < 10; ++i) {
    tf_threadpool_cwq_->AddBlockingTask(tfrt::TaskFunction([&n, &m, &latch] {
                                          {
                                            tensorflow::mutex_lock lock(m);
                                            ++n;
                                          }
                                          latch.count_down();
                                        }),
                                        true);
