          return reduction_function_generator_for_type(U32, builder);
        },
        reference_reduction_function_for_uints, unsigned_int_identity);
  }
  Literal literal_2d_;
  Literal literal_3d_;
  uint32_t seed_ = 0xdeadbeef;
};
