      program_id, "test", "main", std::move(mlir_module), client,
      &GetThreadPool(), &ifrt_loaded_variable_registry,
      &ifrt_restore_tensor_registry, work_queue.get(), device_mgr.get(),
      tensorflow::IdentityShapeRepresentationFn(),
